import pickle, io

ALLOWED = {
    ('numpy._core.multiarray', '_reconstruct'),
    ('numpy.core.multiarray', '_reconstruct'),
    ('numpy', 'ndarray'),
    ('numpy', 'dtype'),
    ('collections', 'OrderedDict'),
    ('builtins', 'dict'),
    ('builtins', 'tuple'),
}
referenced = set()

class SafeUnpickler(pickle.Unpickler):
    def find_class(self, module, name):
        key = (module, name)
        referenced.add(key)
        if key not in ALLOWED:
            raise pickle.UnpicklingError(f"Blocked global: {module}.{name}")
        import importlib
        return getattr(importlib.import_module(module), name)

for i in range(1, 11):
    path = f"model_{i:02d}.pkl"
    with open(path, 'rb') as f:
        try:
            obj = SafeUnpickler(f).load()
        except Exception as e:
            print(f"{path}: FAILED -> {type(e).__name__}: {e}")
            continue
    if not isinstance(obj, dict):
        print(f"{path}: top-level type = {type(obj).__name__}")
        continue
    meta = {k: v for k, v in obj.items() if k != 'state_dict'}
    print(f"{path}: {meta}")
print()
print("All globals referenced:", sorted(referenced))
EOF"}

